"use client";

import { useActionState, useState } from "react";
import { topupCreate, topupConfirm, type ActionState } from "@/lib/actions";
import { formatRp, TOKEN_PRICE_RP } from "@/lib/tokens";

const PRESETS = [2, 4, 10, 20];

export default function TopupClient() {
  const [qty, setQty] = useState(4);
  const [createState, createAction, creating] = useActionState<ActionState, FormData>(topupCreate, {});
  const [confirmState, confirmAction, confirming] = useActionState<ActionState, FormData>(topupConfirm, {});

  return (
    <div style={{ display: "grid", gap: 16 }}>
      <div
        style={{
          background: "#fff",
          border: "1px solid #e2e8f0",
          borderRadius: 12,
          padding: 18,
        }}
      >
        <div style={{ fontSize: 12, fontWeight: 800, color: "#0f172a", marginBottom: 8 }}>
          1. Pilih jumlah token (@{formatRp(TOKEN_PRICE_RP)})
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {PRESETS.map((p) => (
            <button
              key={p}
              type="button"
              onClick={() => setQty(p)}
              style={{
                border: "1px solid #dbeafe",
                background: qty === p ? "#2563eb" : "#eff6ff",
                color: qty === p ? "#fff" : "#2563eb",
                borderRadius: 10,
                padding: "10px 16px",
                fontSize: 12,
                fontWeight: 800,
              }}
            >
              {p} token
            </button>
          ))}
        </div>
        <div style={{ fontSize: 13, fontWeight: 800, color: "#0f172a", marginTop: 12 }}>
          Total: {formatRp(qty * TOKEN_PRICE_RP)}
        </div>
        <form action={createAction} style={{ marginTop: 12 }}>
          <input type="hidden" name="qty" value={qty} />
          <button
            type="submit"
            disabled={creating}
            style={{
              background: "#0f172a",
              color: "#fff",
              border: 0,
              borderRadius: 10,
              padding: "12px 18px",
              fontSize: 12,
              fontWeight: 800,
            }}
          >
            {creating ? "Membuat order…" : "Buat Order"}
          </button>
        </form>
        {createState.message && (
          <p style={{ fontSize: 12, color: "#dc2626", fontWeight: 700 }}>{createState.message}</p>
        )}
      </div>

      {createState.orderId && (
        <div
          style={{
            background: "#eff6ff",
            border: "1px solid #bfdbfe",
            borderRadius: 12,
            padding: 18,
          }}
        >
          <div style={{ fontSize: 12, fontWeight: 800, color: "#0f172a" }}>
            2. Bayar (simulasi) — Order #{createState.orderId} · {formatRp(createState.amountRp ?? 0)}
          </div>
          <p style={{ fontSize: 12, color: "#475569" }}>
            Ini pembayaran pura-pura. Klik tombol di bawah untuk menganggap pembayaran berhasil.
          </p>
          <form action={confirmAction}>
            <input type="hidden" name="orderId" value={createState.orderId} />
            <button
              type="submit"
              disabled={confirming}
              style={{
                background: "#16a34a",
                color: "#fff",
                border: 0,
                borderRadius: 10,
                padding: "12px 18px",
                fontSize: 12,
                fontWeight: 800,
              }}
            >
              {confirming ? "Memproses…" : "Saya Sudah Bayar (Simulasi)"}
            </button>
          </form>
        </div>
      )}

      {(confirmState.paidQty || confirmState.message) && (
        <p
          style={{
            fontSize: 12,
            fontWeight: 700,
            color: confirmState.paidQty ? "#166534" : "#dc2626",
          }}
        >
          {confirmState.paidQty
            ? `Berhasil! ${confirmState.paidQty} token masuk ke dompetmu.`
            : confirmState.message}
        </p>
      )}
    </div>
  );
}
